    <section class="section products-section"><div class="section-heading"><div><p class="eyebrow">JUST LANDED</p><h2>New to the <i>royal edit.</i></h2></div><a class="text-link" href="index.php?page=new">See new arrivals →</a></div><div class="product-grid"><?php foreach($new as $product) product_card($product); ?></div></section>
    <section class="values"><article><span>01</span><h3>Signature detail</h3><p>Distinct prints, trims, and embroidery with purpose.</p></article><article><span>02</span><h3>Heritage, reworked</h3><p>Traditional references expressed with a modern eye.</p></article><article><span>03</span><h3>Comfort in form</h3><p>Pieces meant to move with every occasion.</p></article><article><span>04</span><h3>Find your fit</h3><p>Clear garment measurements for confident ordering.</p></article></section>
    <section class="cta"><p class="eyebrow">THE JOAM COLLECTION</p><h2>Make every entrance<br><i>your own.</i></h2><div class="button-row center"><a class="button" href="index.php?page=shop">Enter the collection <span>→</span></a><a class="text-link" href="index.php?page=size-guide">View size guide</a></div></section>
    <?php render_footer();
}

function product_card(array $p): void { $price=product_price($p); $discount=$p['discount_price'] !== null ? round((1-$price/(float)$p['price'])*100) : 0; ?>
