<?php }

function shop_page(bool $onlyNew): void {
    $pdo=db(); $categories=$pdo->query('SELECT name FROM categories WHERE active=1 ORDER BY name')->fetchAll(); $where=['p.status="active"']; $params=[];
    if ($onlyNew) $where[]='p.is_new=1';
    $query=trim($_GET['q'] ?? ''); if($query !== '') { $where[]='(p.name LIKE ? OR p.description LIKE ? OR c.name LIKE ?)'; $params=array_merge($params, ["%$query%","%$query%","%$query%"]); }
    $category=trim($_GET['category'] ?? ''); if($category !== '') { $where[]='c.name=?'; $params[]=$category; }
    $gender=trim($_GET['gender'] ?? ''); if($gender !== '') { $where[]='p.gender=?'; $params[]=$gender; }
    $sort=$_GET['sort'] ?? 'newest'; $ordering=['low'=>'COALESCE(p.discount_price,p.price) ASC','high'=>'COALESCE(p.discount_price,p.price) DESC','popular'=>'p.views DESC','newest'=>'p.created_at DESC'];
    $stmt=$pdo->prepare('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE '.implode(' AND ',$where).' ORDER BY '.($ordering[$sort]??$ordering['newest'])); $stmt->execute($params); $products=$stmt->fetchAll();
    render_header($onlyNew ? 'New Arrivals' : 'Shop'); ?>
    <section class="shop-intro"><p class="eyebrow"><?=$onlyNew ? 'JUST IN / THE ROYAL EDIT' : 'THE JOAM COLLECTION'?></p><h1><?=$onlyNew ? 'New <i>arrivals.</i>' : 'Wear your <i>signature.</i>'?></h1><p><?=$onlyNew ? 'Fresh native sets, coordinated layers, and essential pieces made to stand apart.' : 'Native sets, heritage tunics, coordinated tracksuits, and refined staples—each selected for an unmistakable finish.'?></p></section>
    <section class="shop-layout"><aside class="filters"><form method="get"><input type="hidden" name="page" value="<?=$onlyNew?'new':'shop'?>"><label>Search<input name="q" value="<?=h($query)?>" placeholder="Find a set, tunic, polo..."></label><label>Category<select name="category"><option value="">All categories</option><?php foreach($categories as $c): ?><option <?=$category===$c['name']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><label>For<select name="gender"><option value="">Everyone</option><?php foreach(['Women','Men','Unisex'] as $g): ?><option <?=$gender===$g?'selected':''?>><?=$g?></option><?php endforeach;?></select></label><label>Sort by<select name="sort"><option value="newest" <?=$sort==='newest'?'selected':''?>>Newest</option><option value="low" <?=$sort==='low'?'selected':''?>>Price: low to high</option><option value="high" <?=$sort==='high'?'selected':''?>>Price: high to low</option><option value="popular" <?=$sort==='popular'?'selected':''?>>Most loved</option></select></label><button class="button">Apply filters</button></form></aside><div class="shop-products"><div class="results-bar"><span><?=count($products)?> pieces in the collection</span><button class="filter-toggle">Filter +</button></div><?php if($products): ?><div class="product-grid"><?php foreach($products as $product) product_card($product); ?></div><?php else: ?><div class="empty-state"><p class="eyebrow">no matches yet</p><h2>Try a different <i>search.</i></h2><a class="button" href="index.php?page=shop">See all products</a></div><?php endif;?></div></section>
    <?php render_footer();
}

